$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
  Well-ordered recursion
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $c wrecs $.

  $( Declare syntax for the well-ordered recursive function generator. $)
  cwrecs $a class wrecs ( R , A , F ) $.

  $( Define the well-ordered recursive function generator.  This function takes
     the usual expressions from recursion theorems and forms a unified
     definition.  Specifically, given a function ` F ` , a relation ` R ` , and
     a base set ` A ` , this definition generates a function
     ` G = wrecs ( R , A , F ) ` that has property that, at any point
     ` x e. A ` , ` ( G `` x ) = ( F `` ( G |`` Pred ( R , A , x ) ) ) ` .  See
     ~ wfr1 , ~ wfr2 , and ~ wfr3 .  (Contributed by Scott Fenton, 7-Jun-2018.)
     (Revised by BJ, 27-Oct-2024.) $)
  df-wrecs $a |- wrecs ( R , A , F ) = frecs ( R , A , ( F o. 2nd ) ) $.

  $( General equality theorem for the well-ordered recursive function
     generator.  (Contributed by Scott Fenton, 7-Jun-2018.)  (Proof shortened
     by Scott Fenton, 17-Nov-2024.) $)
  wrecseq123 $p |- ( ( R = S /\ A = B /\ F = G ) ->
                     wrecs ( R , A , F ) = wrecs ( S , B , G ) ) $=
    ( wceq c2nd ccom cfrecs cwrecs coeq1 frecseq123 syl3an3 df-wrecs 3eqtr4g
    w3a ) CDGZABGZEFGZQACEHIZJZBDFHIZJZACEKBDFKTRSUAUCGUBUDGEFHLABCDUAUCMNACEOB
    DFOP $.

  ${
    nfwrecs.1 $e |- F/_ x R $.
    nfwrecs.2 $e |- F/_ x A $.
    nfwrecs.3 $e |- F/_ x F $.
    $( Bound-variable hypothesis builder for the well-ordered recursive
       function generator.  (Contributed by Scott Fenton, 9-Jun-2018.)  (Proof
       shortened by Scott Fenton, 17-Nov-2024.) $)
    nfwrecs $p |- F/_ x wrecs ( R , A , F ) $=
      ( cwrecs c2nd ccom cfrecs df-wrecs nfcv nfco nffrecs nfcxfr ) ABCDHBCDIJZ
      KBCDLABCQEFADIGAIMNOP $.
  $}

  $( Equality theorem for the well-ordered recursive function generator.
     (Contributed by Scott Fenton, 7-Jun-2018.) $)
  wrecseq1 $p |- ( R = S -> wrecs ( R , A , F ) = wrecs ( S , A , F ) ) $=
    ( wceq cwrecs eqid wrecseq123 mp3an23 ) BCEAAEDDEABDFACDFEAGDGAABCDDHI $.

  $( Equality theorem for the well-ordered recursive function generator.
     (Contributed by Scott Fenton, 7-Jun-2018.) $)
  wrecseq2 $p |- ( A = B -> wrecs ( R , A , F ) = wrecs ( R , B , F ) ) $=
    ( wceq cwrecs eqid wrecseq123 mp3an13 ) CCEABEDDEACDFBCDFECGDGABCCDDHI $.

  $( Equality theorem for the well-ordered recursive function generator.
     (Contributed by Scott Fenton, 7-Jun-2018.) $)
  wrecseq3 $p |- ( F = G -> wrecs ( R , A , F ) = wrecs ( R , A , G ) ) $=
    ( wceq cwrecs eqid wrecseq123 mp3an12 ) BBEAAECDEABCFABDFEBGAGAABBCDHI $.

  ${
    $( Move class substitution in and out of the well-founded recursive
       function generator.  (Contributed by ML, 25-Oct-2020.)  (Revised by
       Scott Fenton, 18-Nov-2024.) $)
    csbwrecsg $p |- ( A e. V -> [_ A / x ]_ wrecs ( R , D , F ) =
                   wrecs ( [_ A / x ]_ R , [_ A / x ]_ D , [_ A / x ]_ F ) ) $=
      ( wcel c2nd ccom cfrecs csb cwrecs csbfrecsg wceq csbcog csbconstg coeq2d
      eqid eqtrd df-wrecs frecseq123 mp3an12i csbeq2i 3eqtr4g ) BFGZABCDEHIZJZK
      ZABCKZABDKZABEKZHIZJZABCDELZKUIUJUKLUEUHUIUJABUFKZJZUMABCDUFFMUJUJNUIUINU
      EUOULNUPUMNUJRUIRUEUOUKABHKZIULABEHFOUEUQHUKABHFPQSUIUIUJUJUOULUAUBSABUNU
      GCDETUCUIUJUKTUD $.
