$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
  Ordinal arithmetic
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $( Introduce new constant symbols. $)
  $c 1o $.  $( The ordinal number 1 $)
  $c 2o $.  $( The ordinal number 2 $)
  $c 3o $.  $( The ordinal number 3 $)
  $c 4o $.  $( The ordinal number 4 $)
  $c +o $.  $( Ordinal addition operation (plus subscript o) $)
  $c .o $.  $( Ordinal multiplication operation (center dot subscript o) $)
  $c ^o $.  $( Ordinal exponentiation operation (caret subscript o) $)

  $( Extend the definition of a class to include the ordinal number 1. $)
  c1o $a class 1o $.

  $( Extend the definition of a class to include the ordinal number 2. $)
  c2o $a class 2o $.

  $( Extend the definition of a class to include the ordinal number 3. $)
  c3o $a class 3o $.

  $( Extend the definition of a class to include the ordinal number 4. $)
  c4o $a class 4o $.

  $( Extend the definition of a class to include the ordinal addition
     operation. $)
  coa $a class +o $.

  $( Extend the definition of a class to include the ordinal multiplication
     operation. $)
  comu $a class .o $.

  $( Extend the definition of a class to include the ordinal exponentiation
     operation. $)
  coe $a class ^o $.

  $( Define the ordinal number 1.  Definition 2.1 of [Schloeder] p. 4.
     (Contributed by NM, 29-Oct-1995.) $)
  df-1o $a |- 1o = suc (/) $.

  $( Define the ordinal number 2.  Lemma 3.17 of [Schloeder] p. 10.
     (Contributed by NM, 18-Feb-2004.) $)
  df-2o $a |- 2o = suc 1o $.

  $( Define the ordinal number 3.  (Contributed by Mario Carneiro,
     14-Jul-2013.) $)
  df-3o $a |- 3o = suc 2o $.

  $( Define the ordinal number 4.  (Contributed by Mario Carneiro,
     14-Jul-2013.) $)
  df-4o $a |- 4o = suc 3o $.

  ${
    $d x y z $.
    $( Define the ordinal addition operation.  (Contributed by NM,
       3-May-1995.) $)
    df-oadd $a |- +o = ( x e. On , y e. On |->
                ( rec ( ( z e. _V |-> suc z ) , x ) ` y ) ) $.

    $( Define the ordinal multiplication operation.  (Contributed by NM,
       26-Aug-1995.) $)
    df-omul $a |- .o = ( x e. On , y e. On |->
                ( rec ( ( z e. _V |-> ( z +o x ) ) , (/) ) ` y ) ) $.

    $( Define the ordinal exponentiation operation.  (Contributed by NM,
       30-Dec-2004.) $)
    df-oexp $a |- ^o = ( x e. On , y e. On |->
                   if ( x = (/) , ( 1o \ y ) ,
                 ( rec ( ( z e. _V |-> ( z .o x ) ) , 1o ) ` y ) ) ) $.
  $}

  $( Expanded value of the ordinal number 1.  Definition 2.1 of [Schloeder]
     p. 4.  (Contributed by NM, 4-Nov-2002.) $)
  df1o2 $p |- 1o = { (/) } $=
    ( c1o c0 csuc csn df-1o suc0 eqtri ) ABCBDEFG $.

  $( Expanded value of the ordinal number 2.  (Contributed by Mario Carneiro,
     14-Aug-2015.) $)
  df2o3 $p |- 2o = { (/) , 1o } $=
    ( c2o c1o csuc csn cun c0 cpr df-2o df-suc df1o2 uneq1i df-pr eqtr4i 3eqtri
    ) ABCBBDZEZFBGZHBIPFDZOEQBROJKFBLMN $.

  $( Expanded value of the ordinal number 2.  (Contributed by NM,
     29-Jan-2004.) $)
  df2o2 $p |- 2o = { (/) , { (/) } } $=
    ( c2o c0 c1o cpr csn df2o3 df1o2 preq2i eqtri ) ABCDBBEZDFCJBGHI $.

  $( Ordinal 1 is a set.  (Contributed by BJ, 6-Apr-2019.)  (Proof shortened by
     AV, 1-Jul-2022.)  Remove dependency on ~ ax-10 , ~ ax-11 , ~ ax-12 ,
     ~ ax-un .  (Revised by Zhi Wang, 19-Sep-2024.) $)
  1oex $p |- 1o e. _V $=
    ( c1o c0 csn cvv df1o2 snex eqeltri ) ABCDEBFG $.
  $( $j usage '1oex' avoids 'ax-10' 'ax-11' 'ax-12' 'ax-un'; $)

  $( ` 1o ` is an element of ` { (/) , 1o } ` .  (Contributed by Umit Teoman
     Dogan, 10-Jun-2026.) $)
  1oelpr $p |- 1o e. { (/) , 1o } $=
    ( c0 c1o 1oex prid2 ) ABCD $.

  $( ` 2o ` is a set.  (Contributed by BJ, 6-Apr-2019.)  Remove dependency on
     ~ ax-10 , ~ ax-11 , ~ ax-12 , ~ ax-un .  (Proof shortened by Zhi Wang,
     19-Sep-2024.) $)
  2oex $p |- 2o e. _V $=
    ( c2o c0 c1o cpr cvv df2o3 prex eqeltri ) ABCDEFBCGH $.
  $( $j usage '2oex' avoids 'ax-10' 'ax-11' 'ax-12' 'ax-un'; $)

  $( Ordinal 1 is an ordinal number.  (Contributed by NM, 29-Oct-1995.)  Avoid
     ~ ax-un .  (Revised by BTernaryTau, 30-Nov-2024.) $)
  1on $p |- 1o e. On $=
    ( c1o csuc con0 df-1o wcel cvv 0elon 1oex eqeltrri sucexeloni mp2an eqeltri
    c0 ) AMBZCDMCENFENCEGANFDHIMFJKL $.
  $( $j usage '1on' avoids 'ax-un'; $)

  $( Ordinal 2 is an ordinal number.  (Contributed by NM, 18-Feb-2004.)  (Proof
     shortened by Andrew Salmon, 12-Aug-2011.)  Avoid ~ ax-un .  (Revised by
     BTernaryTau, 30-Nov-2024.) $)
  2on $p |- 2o e. On $=
    ( c2o c1o csuc con0 df-2o wcel cvv 2oex eqeltrri sucexeloni mp2an eqeltri
    1on ) ABCZDEBDFNGFNDFMANGEHIBGJKL $.
  $( $j usage '2on' avoids 'ax-un'; $)

  $( Ordinal two is not zero.  (Contributed by Scott Fenton, 17-Jun-2011.) $)
  2on0 $p |- 2o =/= (/) $=
    ( c2o c1o csuc c0 df-2o nsuceq0 eqnetri ) ABCDEBFG $.

  $( Ordinal 3 is an ordinal class.  (Contributed by BTernaryTau,
     6-Jan-2025.) $)
  ord3 $p |- Ord 3o $=
    ( c3o word c2o csuc con0 wcel 2on eloni ordsuci mp2b wceq df-3o ordeq ax-mp
    wb mpbir ) ABZCDZBZCEFCBSGCHCIJARKQSOLARMNP $.
  $( $j usage 'ord3' avoids 'ax-un'; $)

  $( Ordinal 3 is an ordinal number.  (Contributed by Mario Carneiro,
     5-Jan-2016.) $)
  3on $p |- 3o e. On $=
    ( c3o c2o csuc con0 df-3o 2on onsuci eqeltri ) ABCDEBFGH $.

  $( Ordinal 4 is an ordinal number.  (Contributed by Mario Carneiro,
     5-Jan-2016.) $)
  4on $p |- 4o e. On $=
    ( c4o c3o csuc con0 df-4o 3on onsuci eqeltri ) ABCDEBFGH $.

  $( Ordinal one is not equal to ordinal zero.  (Contributed by NM,
     26-Dec-2004.)  (Proof shortened by Umit Teoman Dogan, 10-Jun-2026.) $)
  1n0 $p |- 1o =/= (/) $=
    ( c1o c0 csuc df-1o nsuceq0 eqnetri ) ABCBDBEF $.

  $( Obsolete version of ~ 1n0 as of 10-Jun-2026.  (Contributed by NM,
     26-Dec-2004.)  (Proof modification is discouraged.)
     (New usage is discouraged.) $)
  1n0OLD $p |- 1o =/= (/) $=
    ( c1o c0 csn df1o2 0ex snnz eqnetri ) ABCBDBEFG $.

  $( 1 is not a limit ordinal.  (Contributed by BTernaryTau, 1-Dec-2024.) $)
  nlim1 $p |- -. Lim 1o $=
    ( c1o wlim word c0 wne cuni wceq w3a csn 1n0 0ex unisn neeqtrri unieqi neii
    df1o2 simp3 mto df-lim mtbir ) ABACZADEZAAFZGZHZUEUDAUCADIZFZUCADUGJDKLMAUF
    PNMOUAUBUDQRAST $.
  $( $j usage 'nlim1' avoids 'ax-un'; $)

  $( 2 is not a limit ordinal.  (Contributed by BTernaryTau, 1-Dec-2024.) $)
  nlim2 $p |- -. Lim 2o $=
    ( c2o wlim word c0 wne cuni wceq w3a c1o wcel cpr 1oelpr df2o3 eleqtrri 1on
    onirri eleq2 mtbiri mt2 neir cun unieqi 0ex 1oex unipr 3eqtri neeqtrri neii
    0un simp3 mto df-lim mtbir ) ABACZADEZAAFZGZHZURUQAUPAIUPAIAIGZIAJZIDIKZALM
    NUSUTIIJIOPAIIQRSTUPVAFDIUAIAVAMUBDIUCUDUEIUIUFUGUHUNUOUQUJUKAULUM $.
  $( $j usage 'nlim2' avoids 'ax-un'; $)

  $( Cartesian products with the singletons of ordinals 0 and 1 are disjoint.
     (Contributed by NM, 2-Jun-2007.) $)
  xp01disj $p |- ( ( A X. { (/) } ) i^i ( C X. { 1o } ) ) = (/) $=
    ( c0 c1o wne csn cxp cin wceq 1n0 necomi xpsndisj ax-mp ) CDEACFGBDFGHCIDCJ
    KACBDLM $.

  $( Cartesian products with the singletons of ordinals 0 and 1 are disjoint.
     (Contributed by Jim Kingdon, 11-Jul-2023.) $)
  xp01disjl $p |- ( ( { (/) } X. A ) i^i ( { 1o } X. C ) ) = (/) $=
    ( c0 c1o wne csn cin wceq cxp 1n0 necomi disjsn2 xpdisj1 mp2b ) CDECFZDFZGC
    HOAIPBIGCHDCJKCDLOPABMN $.

  $( Two ways to express that an ordinal class is positive.  (Contributed by
     NM, 21-Dec-2004.) $)
  ordgt0ge1 $p |- ( Ord A -> ( (/) e. A <-> 1o C_ A ) ) $=
    ( word c0 wcel csuc wss c1o con0 0elon ordelsuc mpan df-1o sseq1i bitr4di
    wb ) ABZCADZCEZAFZGAFCHDPQSOICAHJKGRALMN $.

  $( An ordinal greater than or equal to 1 is nonzero.  (Contributed by NM,
     21-Dec-2004.) $)
  ordge1n0 $p |- ( Ord A -> ( 1o C_ A <-> A =/= (/) ) ) $=
    ( word c0 wcel c1o wss wne ordgt0ge1 ord0eln0 bitr3d ) ABCADEAFACGAHAIJ $.

  $( Membership in ordinal one.  (Contributed by NM, 5-Jan-2005.) $)
  el1o $p |- ( A e. 1o <-> A = (/) ) $=
    ( c1o wcel c0 csn wceq df1o2 eleq2i 0ex elsn2 bitri ) ABCADEZCADFBLAGHADIJK
    $.

  $( An ordinal that is not 0 or 1 contains 1.  (Contributed by BTernaryTau,
     1-Dec-2024.) $)
  ord1eln01 $p |- ( Ord A -> ( 1o e. A <-> ( A =/= (/) /\ A =/= 1o ) ) ) $=
    ( word c1o wcel c0 wne wa ne0i wceq 1on onirri eleq2 mtbiri necon2ai jca wo
    wn el1o biimpi necon3ai nesym anim12ci pm4.56 onordi ordtri2 mpan imbitrrid
    sylib wb impbid2 ) ABZCADZAEFZACFZGZULUMUNACHULACACIULCCDCJKACCLMNOUOULUKCA
    IZACDZPQZUOUPQZUQQZGURUMUTUNUSUQAEUQAEIARSTUNUSACUASUBUPUQUCUHCBUKULURUICJU
    DCAUEUFUGUJ $.
  $( $j usage 'ord1eln01' avoids 'ax-un'; $)

  $( An ordinal that is not 0, 1, or 2 contains 2.  (Contributed by
     BTernaryTau, 1-Dec-2024.) $)
  ord2eln012 $p |- ( Ord A ->
      ( 2o e. A <-> ( A =/= (/) /\ A =/= 1o /\ A =/= 2o ) ) ) $=
    ( word c2o wcel c0 wne c1o w3a ne0i wceq 2on0 nemtbir eleq2 mtbiri necon2ai
    el1o 2on onirri 3jca wn wo wa nesym biimpi 3ad2ant3 cpr simp1 nelprd eleq2i
    simp2 df2o3 sylnibr jca pm4.56 sylib onordi ordtri2 mpan imbitrrid impbid2
    wb ) ABZCADZAEFZAGFZACFZHZVCVDVEVFACIVCAGAGJVCCGDZVHCEKCPLAGCMNOVCACACJVCCC
    DCQRACCMNOSVGVCVBCAJZACDZUATZVGVITZVJTZUBVKVGVLVMVFVDVLVEVFVLACUCUDUEVGAEGU
    FZDVJVGAEGVDVEVFUGVDVEVFUJUHCVNAUKUIULUMVIVJUNUOCBVBVCVKVACQUPCAUQURUSUT $.
  $( $j usage 'ord2eln012' avoids 'ax-un'; $)

  $( A limit ordinal contains 1.  (Contributed by BTernaryTau, 1-Dec-2024.) $)
  1ellim $p |- ( Lim A -> 1o e. A ) $=
    ( wlim c1o wcel c0 wceq nlim0 limeq mtbiri necon2ai nlim1 word wa wb limord
    wne ord1eln01 syl mpbir2and ) ABZCADZAEPZACPZTAEAEFTEBGAEHIJTACACFTCBKACHIJ
    TALUAUBUCMNAOAQRS $.
