    pmvalg $p |- ( ( A e. C /\ B e. D ) ->
                  ( A ^pm B ) = { f e. ~P ( B X. A ) | Fun f } ) $=
      ( vx vy wcel wa cv wfun cxp cpw crab cvv cpm wceq elex pweqd rabeqdv wss
      co ssrab2 xpexg ancoms pwexd ssexg xpeq2 xpeq1 df-pm ovmpog 3expia syl2an
      sylancr wi mpd ) ACHZBDHZIZEJKZEBALZMZNZOHZABPUBVCQZUSVCVBUAVBOHVDUTEVBUC
